        \draw[-stealth, line width=0.5mm](lem48) -- (r2);
        \draw[-stealth, line width=0.5mm](lem47) -- (lem48);
        \draw[-stealth, line width=0.5mm](lem49) -- (lem48);

        \node[myNodeNarrow, line width=1pt, text width=2.2cm](lem412) at (3.25, -11.2)
            {{\cref{lem:constReg:expectedValue:upperBound}}};
        \node[myNodeNarrow, line width=1pt, text width=2.2cm](lem413) at (6, -11.2)
            {{\cref{lem:constReg:expectedValue:feasibility}}};
        \node[myNodeNarrow, line width=1pt, text width=2.2cm](lem414) at (8.75, -11.2)
            {{\cref{lem:constReg:expectedValue:ub2}}};

        \draw[-stealth, line width=0.5mm](lem411) -- (r3);
        \draw[-stealth, line width=0.5mm](lem410) -- (r3);
        \draw[-stealth, line width=0.5mm](lem412) -- (lem410);
        \draw[-stealth, line width=0.5mm](lem413) -- (lem410);
        \draw[-stealth, line width=0.5mm](lem414) -- (lem410);

        \end{tikzpicture}
        \caption{\textit{Outline of the proof of \cref{thm:main}.} 
        The proof of \cref{thm:main} follows a structure analogous to the proof of the sample complexity of PIU learning (\cref{thm:sampleComplexity}): 
        we construct a sequence of instances of \pERM{} and output the intersection of all the (approximate) solutions $H_1,H_2,\dots$ to the instances created.
        To approximately solve each instance created, we use an approximation algorithm for \pERM{} (constructed in \cref{thm:constReg}).
        This is the main new technical ingredient in the proof of \cref{thm:main} compared to \cref{thm:sampleComplexity}.
        }
        \label{fig:outline:compComplexity}
    \end{figure}

