\begin{figure}[h]
        \centering
        \vspace{4mm}
        \begin{tikzpicture}[node distance=2.5cm, auto]
        \node[myNodeNarrow, line width=1pt, text width=7.25cm] (thmAgnostic) at (-4.5,0) 
            {{Sample Efficient Algorithm (Agnostic)\\[1mm] \cref{new:thm:perm:robust}}};

        \node[myNodeNarrow, line width=1pt, text width=7.25cm] (thmRealizable) at (4.5,0) 
            {{Sample Efficient Algorithm (Realizable)\\[1mm] \cref{thm:sampleComplexity}}};

        \draw[-stealth, line width=0.5mm] (thmAgnostic) -- (thmRealizable); 

        \node[myNode, line width=1pt, text width=7.25cm] (lemEasy) at (-4.5,-2.2) 
            {{Upper bound on False Negative Error\\ $\cD(\optset\setminus H)~{\leq}~\poly_q(\eps)$\\[1mm]\cref{lem:perm:easy}}};

        \node[myNode, line width=1pt, text width=7.25cm] (lemHard) at (4.5,-2.2) 
            {{Upper bound on False Positive Error\\ $\cD(H\setminus\optset)~{\leq}~\poly_q(\eps)$\\[1mm]\cref{lem:perm:hard}}};

        \draw[-stealth, line width=0.5mm] (lemEasy) -- (thmAgnostic); 
        \draw[-stealth, line width=0.5mm] (lemHard) -- (thmAgnostic); 

        \node[myNode, line width=1pt, text width=4.5cm] (lemTerms23) at (0.15,-4.65) 
            {$\cD(H'){\,-\,}\cD(\optset){\,\leq\,}\poly_q(\eps)$\\$\cD(\optset\setminus H){\,\leq\,}\poly_q(\eps)$\\[1mm] \cref{lem:sampleComplexity:Hard:UBterms23}};
        \node[myNode, line width=1pt, text width=4.5cm, minimum height=1.75cm] (lemTerm1) at (5.88,-4.65) 
            {$\cD(H)-\cD(H')~{\leq}~\poly_q(\eps)$\\[3mm]\cref{lem:sampleComplexity:Hard:UBterm1}};

        \draw[-stealth, line width=0.5mm] (lemTerms23) -- (lemHard); 
        \draw[-stealth, line width=0.5mm] (lemTerm1.north) -- ($(lemTerm1.north |- lemHard.south)$);


        \node[myNode, line width=1pt, text width=4.5cm] (lemFeasibility) at (5.88,-6.85) 
            {Feasibility of $H'$\\[1mm]\cref{lem:sampleComplexity:Hard:feasibility}};

        \draw[-stealth, line width=0.5mm] (lemFeasibility) -- (lemTerm1); 

        \node[myNode, dashed, line width=1pt, text width=7.25cm] (unifConv) at (-4.5,-6.85) 
            {Second-Order Uniform Convergence\\[1mm]\cref{thm:unifConvergence} from, \eg{},  \cite{Boucheron_Bousquet_Lugosi_2005}};

        \draw[-stealth, line width=0.5mm] (unifConv) -- (lemFeasibility); 
        \draw[-stealth, line width=0.5mm] (unifConv) -- (lemTerms23); 
        \draw[-stealth, line width=0.5mm] (unifConv) -- (lemEasy); 

        \end{tikzpicture}
        \caption{Outline of the proofs of \cref{thm:sampleComplexity:bothSided,new:thm:perm:robust}.}
        \label{fig:outline:sampleComplexity}
    \end{figure}

